int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("args checker source.pb geometry-dir output-dir");fs::path geometry=argv[3],output=argv[4];fs::create_directories(output);std::string stem="0-1-1-range";std::ofstream result(output/"corruptions.tsv");result<<"case\texit_code\trefused\n";for(std::string kind:{"xyz_shift","xyz_nan","pixel_row","feature_range","features_extra_channel","xyz_truncated","xyz_extra","missing_return"}){fs::path dest=output/kind;fs::create_directory(dest);for(auto&item:fs::directory_iterator(geometry))if(item.is_regular_file())fs::create_symlink(item.path(),dest/item.path().filename());std::string suffix=(kind=="pixel_row")?".pixels.bin":(kind=="feature_range"||kind=="features_extra_channel")?".features.bin":".xyz.bin";auto path=dest/(stem+suffix);fs::remove(path);if(kind!="missing_return"){fs::copy_file(geometry/(stem+suffix),path);if(kind=="xyz_truncated")fs::resize_file(path,fs::file_size(path)-1);else if(kind=="xyz_extra"||kind=="features_extra_channel"){std::ofstream f(path,std::ios::binary|std::ios::app);if(kind=="xyz_extra")f.put('x');else{float nlz=0;f.write((char*)&nlz,4);}}else{std::fstream f(path,std::ios::binary|std::ios::in|std::ios::out);if(kind=="pixel_row"){int32_t value;f.read((char*)&value,4);value++;f.seekp(0);f.write((char*)&value,4);}else if(kind=="feature_range"){float value;f.read((char*)&value,4);value+=1.f;f.seekp(0);f.write((char*)&value,4);}else{double value;f.read((char*)&value,8);value=kind=="xyz_nan"?std::numeric_limits<double>::quiet_NaN():value+1.;f.seekp(0);f.write((char*)&value,8);}}}pid_t pid=fork();if(pid<0)throw std::runtime_error("fork");if(pid==0){execl(argv[1],argv[1],argv[2],dest.c_str(),(dest/"audit.tsv").c_str(),(char*)nullptr);_exit(127);}int status;if(waitpid(pid,&status,0)!=pid||!WIFEXITED(status))throw std::runtime_error("child status");int rc=WEXITSTATUS(status);result<<kind<<'\t'<<rc<<'\t'<<(rc==1)<<'\n';result.flush();if(rc!=1)throw std::runtime_error("corrupt serialized stream accepted: "+kind);}std::cout<<"PASS 8 serialized corruption refusals\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
